SELECT analytics_order_facts.category, SUM(analytics_order_facts.net_revenue) / CAST(NULLIF(COUNT(DISTINCT analytics_order_facts.order_id), 0) AS DECIMAL) AS average_order_value FROM analytics_order_facts WHERE analytics_order_facts.year = 2025 AND analytics_order_facts.month = 6 AND analytics_order_facts.region = 'Central' AND analytics_order_facts.channel = 'retail' AND analytics_order_facts.customer_segment = 'mid_market' GROUP BY analytics_order_facts.category ORDER BY average_order_value DESC, analytics_order_facts.category ASC LIMIT 12
